    const path = []
    let current = boards.find(b => b.title === boardTitle || b.id === boardTitle)
    const visited = new Set()
    while (current) {
      const key = current.id || current.title
      if (visited.has(key)) break
      visited.add(key)
      path.unshift(current)
      if (current.parent_id) {
